export interface Village {
  id: string;
  name: string;
  emoji: string;
  description: string;
  hidden?: boolean;
}

export function toVillageId(s: string) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

